#!/usr/bin/env python3
"""Fix the view order in the cloud-connector SQL dump generated by the
ArtifactsTest: the "...Files" view must be created before the
"...FileData" view, as the latter depends on the former. mysqldump
emits views in alphabetical order, which is the wrong one here.

Usage: fix-cloud-connector-dump.py INPUT.sql OUTPUT.sql
"""
import re
import sys

HEADER = re.compile(r'^-- Final view structure for view `([^`]+)`$', re.M)


def main(src, dst):
  with open(src, encoding='utf-8') as f:
    sql = f.read()

  matches = list(HEADER.finditer(sql))
  # a block starts at the "--" line preceding the header, and ends at the next block or EOF
  starts = [sql.rindex('--\n', 0, m.start()) for m in matches]
  ends = starts[1:] + [None]
  if ends[-1] is None:
    tail = re.search(r'^-- Dump completed', sql[starts[-1]:], re.M) if matches else None
    ends[-1] = starts[-1] + tail.start() if tail else len(sql)
  blocks = {m.group(1): (s, e) for m, s, e in zip(matches, starts, ends)}

  files = [n for n in blocks if n.endswith('Files')]
  fileData = [n for n in blocks if n.endswith('FileData')]
  if not files or not fileData:
    sys.exit('Could not find the Files and FileData views in ' + src)
  if len(files) != 1 or len(fileData) != 1:
    sys.exit('Ambiguous Files / FileData views in ' + src)
  filesName, fileDataName = files[0], fileData[0]

  fs, fe = blocks[filesName]
  ds, de = blocks[fileDataName]
  if fs < ds:
    print('View order already correct in ' + src, file=sys.stderr)
    out = sql
  else:
    # FileData is currently before Files: swap the two blocks
    # (ds, de) < (fs, fe) are not necessarily adjacent
    out = sql[:ds] + sql[fs:fe] + sql[de:fs] + sql[ds:de] + sql[fe:]

  with open(dst, 'w', encoding='utf-8') as f:
    f.write(out)


if __name__ == '__main__':
  if len(sys.argv) != 3:
    sys.exit(__doc__)
  main(sys.argv[1], sys.argv[2])
